def solve(inputs: dict) -> float:
    rems = inputs['rems']
    mods = inputs['mods']
    x = 0
    m = 1
    for r, mod in zip(rems, mods):
        r %= mod
        # solve x + m*k ≡ r (mod mod)
        a, b = m, mod
        # extended gcd
        def egcd(u, v):
            if v == 0:
                return (u, 1, 0)
            g, x1, y1 = egcd(v, u % v)
            return (g, y1, x1 - (u // v) * y1)
        g, s, t = egcd(a, b)
        if (r - x) % g != 0:
            raise ValueError('no solution')
        lcm = a // g * b
        k = ((r - x) // g * s) % (b // g)
        x = (x + a * k) % lcm
        m = lcm
    return float(x)

